// Lively package only: lets the standalone dream tank start its sim worker when the page is
// loaded from file://, where Chromium refuses `new Worker('sim-worker.js')` (the page's origin
// is opaque). sim-worker-inline.js, generated by build-zip.mjs, puts the worker's source in
// window.__ptWorkerSource; this shim turns it into a blob: worker. Over http(s) it does nothing.
(function () {
  'use strict';
  var Native = window.Worker;
  if (!Native) return;
  function Shimmed(url, options) {
    var href = String(url);
    var src = window.__ptWorkerSource;
    if (typeof src === 'string' && /sim-worker\.js(\?|#|$)/.test(href) && location.protocol === 'file:') {
      var blobUrl = URL.createObjectURL(new Blob([src], { type: 'text/javascript' }));
      return new Native(blobUrl, options);
    }
    return new Native(url, options);
  }
  Shimmed.prototype = Native.prototype;
  window.Worker = Shimmed;
})();
